#!/usr/bin/env bash
set -euo pipefail

# ============================================================================
# Fase 8j -- CONSOLIDADO: 4 correcciones tras probar Fase 8i en real
#
#   a) Se quita la pestaña "Vehiculos" de Flota y Transportistas (Raul pidio
#      revertirla -- "en transportistas ya figuran los vehiculos"). El QR y
#      la matricula del conductor se gestionan ahora directamente desde la
#      propia pestaña "Conductores".
#   b) Conductores: alta con datos personales + transportista + vehiculo (ya
#      sea una matricula existente o una nueva, en el mismo paso), columna
#      "Vehiculo" con QR/reasignar desde la fila, y Desactivar/Reactivar +
#      Eliminar (borrado real, bloqueado solo si el conductor ya tiene
#      envios o jornadas registradas, para no perder historico).
#   c) Se corrige el bug real de "Ningun transportista tiene un vehiculo con
#      capacidad suficiente" pese a tener tipos de hasta 33 pales
#      configurados: la comparativa de transportistas (/optimization/:id/
#      simulate) solo miraba matriculas concretas dadas de alta (Vehicle),
#      no los tipos de vehiculo simplemente declarados por checkbox en
#      Transportistas (CarrierVehicleType) -- ahora cuentan tambien como
#      candidatos.
#   d) Rutas: se puede eliminar una ruta ya creada por error (solo si no
#      tiene ya un envio creado) -- sus pedidos vuelven a quedar pendientes
#      de planificar en vez de desaparecer.
#   e) El Planificador (almacen, fecha y estado del pedido) ya no se
#      resetea al cambiar de pestaña o al navegar fuera y volver -- vivia en
#      estado local que React destruia al desmontar el componente; ahora
#      vive en un store en memoria (planner-filters-store.ts, mismo patron
#      que auth-store.ts) que sobrevive a eso.
#
# Ficheros incluidos:
#   - backend/src/modules/routes/optimization.routes.ts
#   - backend/src/modules/routes/routes.routes.ts
#   - backend/src/modules/vehicles/vehicles.routes.ts
#   - frontend/src/pages/PlannerPage.tsx
#   - frontend/src/pages/masters/CarrierFleetPage.tsx
#   - frontend/src/pages/masters/DriversModal.tsx
#   - frontend/src/pages/masters/VehiclesPage.tsx
#   - frontend/src/pages/planner/PlanificacionTab.tsx
#   - frontend/src/pages/planner/RutasTab.tsx
#   - frontend/src/store/planner-filters-store.ts (nuevo)
#
# Verificado: backend tsc --noEmit (0 errores nuevos frente a la referencia
# ya conocida) + esbuild bundle + smoke test; frontend tsc --noEmit + npm
# run build, ambos sin errores.
#
# Ejecutar desde la raiz del repo (tms-production).
# ============================================================================

if [ ! -d "backend" ] || [ ! -d "frontend" ]; then
  echo "ERROR: ejecuta este script desde la raiz del repo (debe contener backend/ y frontend/)" >&2
  exit 1
fi

echo "Aplicando Fase 8j (revertir pestaña Vehiculos + conductor/vehiculo/QR + fix capacidad + eliminar rutas + fix reseteo Planificador)..."

mkdir -p "$(dirname "backend/src/modules/routes/optimization.routes.ts")"
base64 -d > "backend/src/modules/routes/optimization.routes.ts" <<'B64EOF_0'
